SELECT count(*), sum(rowid=1 AND a IS NULL AND typeof(b)='text' AND b='abcdefghij' AND typeof(c)='integer' AND c=4000), sum(rowid=2 AND typeof(a)='text' AND a=replace(hex(zeroblob(50)), '00', 'abcdefghij') AND typeof(b)='integer' AND b=4000 AND c IS NULL), sum(rowid=3 AND typeof(a)='integer' AND a=4000 AND b IS NULL AND typeof(c)='text' AND c=replace(hex(zeroblob(50000)), '00', 'abcdefghij')) FROM t1;